function drawFrame(now){const w=canvas.width,h=canvas.height,t=tracks[state.selectedTrack]||tracks[0],theme=t.theme,car=cars[state.selected]||cars[0];ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);let horizon=h*.43;let grad=ctx.createLinearGradient(0,0,0,horizon);grad.addColorStop(0,t.sky[0]);grad.addColorStop(1,t.sky[1]);ctx.fillStyle=grad;ctx.fillRect(0,0,w,horizon);ctx.fillStyle=theme==='coast'?'#ffe89b':theme==='city'?'#ff8b79':'#f8dfad';ctx.beginPath();ctx.arc(w*.76,horizon*.52,45,0,Math.PI*2);ctx.fill();drawScenery(w,horizon,theme,now);ctx.fillStyle=t.grass[0];ctx.fillRect(0,horizon,w,h-horizon);
